		"item-add", "--shift", "S001", "--content", "上一班已关闭的巡检事项",
		"--severity", "important", "--constraints", "需复查记录", "--follow", "李四"))
	must("上一班结束前关闭 I003", runCLI(t, dataPath,
		"item-close", "--id", "I003", "--operator", "张三"))
