// S001（张三，白班，已结束）留有三项——I001、I002 结束时未关闭，I003 结束前
// 已关闭；S001 结束后经 H001 把 I001、I002 交给仍在进行中的 S002（李四），
// 两项均确认接收、交接完成；接班后李四又修改过 I001 的四项信息。
func setupReceivedItemForClose(t *testing.T) string {
	t.Helper()
